KEYS = ("app_name", "tile_summary", "cpu_oc_title", "cpu_oc_summary", "cpu_oc_note")

def aapt(s):
    s = escape(s)
    return s.replace("'", "\\'").replace('"', '\\"')

res = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "res")
for loc, vals in T.items():
    d = os.path.join(res, "values" + ("-" + loc if loc else ""))
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, "strings.xml"), "w", encoding="utf-8") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n')
        f.write("<!-- SPDX-License-Identifier: Apache-2.0. Generated by tools/strings.py -->\n<resources>\n")
        for k, v in zip(KEYS, vals):
            f.write(f'    <string name="{k}">{aapt(v)}</string>\n')
        f.write("</resources>\n")
print(len(T) - 1, "Sprachen + Standard")
